  "implementation": "def solve(case):
    import json
    nodes = case['nodes']
    required_symbols = case['required_symbols']
    node_map = {n['id']: n for n in nodes}
    children_map = {}
    for n in nodes:
        pid = n['parent']
        if pid is not None:
            children_map.setdefault(pid, []).append(n['id'])

    # Find root
    root_id = None
    for n in nodes:
        if n['parent'] is None:
            root_id = n['id']
            break
    if root_id is None:
        raise ValueError('No root node')

    # Compute subtree sets (including node itself)
    subtree_cache = {}
    def compute_subtree(nid):
        if nid in subtree_cache:
            return subtree_cache[nid]
        s = {nid}
        for child in children_map.get(nid, []):
            s |= compute_subtree(child)
        subtree_cache[nid] = s
        return s
    for n in nodes:
        compute_subtree(n['id'])

    # All nodes initially retained
    retained = set(node_map.keys())
    removed_order = []

    # Sort nodes: depth descending, then id ascending
    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))

    for nd in sorted_nodes:
        nid = nd['id']
        if nid not in retained:
            continue
        if not nd['removable']:
            continue
        if nd['parent'] is None:
            continue
        # Check that no descendant is retained
        subtree = subtree_cache[nid]
        descendants = subtree - {nid}
        if any(desc in retained for desc in descendants):
            continue
        # Check required symbols after removal
        symbols_after = set()
        for rid in retained:
            if rid not in subtree:
                symbols_after.add(node_map[rid]['symbol'])
        if all(req in symbols_after for req in required_symbols):
            retained -= subtree
            removed_order.append(nid)

    retained_ids = sorted(retained)
    removed_ids = removed_order
    return {
        'removed_node_ids': removed_ids,
        'retained_node_ids': retained_ids
    }"
